    for (let j = m - 1; j >= 0; j -= 1) {
      if (a[i] === b[j]) table[i][j] = table[i + 1][j + 1] + 1
      else table[i][j] = Math.max(table[i + 1][j], table[i][j + 1])
    }
  }
  return table
