 * The three-way merge itself: gathering the changes of both sides into regions
 * and resolving each region.
 */

import { changes } from './diff.js'

function sameLines(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i += 1) if (a[i] !== b[i]) return false
  return true
}

/**
 * The lines a side contributes to a region: its own changed runs together with
 * whatever base context the region reaches beyond them.
 */
function sideLines(document, base, region, own) {
  if (own.length === 0) return base.slice(region.start, region.end)
  let first = own[0]
  let last = own[0]
  for (const change of own) {
    if (change.baseStart < first.baseStart) first = change
    if (change.baseEnd > last.baseEnd) last = change
  }
  const from = first.sideStart - (first.baseStart - region.start)
  const to = last.sideEnd + (region.end - last.baseEnd)
  return document.slice(from, to)
}

/**
 * The regions of the merge, in order: stable runs of base lines and the
 * regions the changes of the two sides cover.
 */
export function regionsOf(mine, base, theirs) {
  const all = []
  for (const change of changes(base, mine)) all.push({ ...change, side: 'mine' })
  for (const change of changes(base, theirs)) all.push({ ...change, side: 'theirs' })
  all.sort((a, b) => a.baseStart - b.baseStart || (a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1))

  const regions = []
  let baseAt = 0
  let index = 0
  while (index < all.length) {
    const first = all[index]
    let start = first.baseStart
    let end = first.baseEnd
    const group = [first]
    index += 1
    while (index < all.length && all[index].baseStart <= end) {
      end = Math.max(end, all[index].baseEnd)
      group.push(all[index])
      index += 1
    }
    if (start > baseAt) regions.push({ kind: 'stable', lines: base.slice(baseAt, start) })
    const region = { start, end }
    const mineLines = sideLines(mine, base, region, group.filter(c => c.side === 'mine'))
    const theirLines = sideLines(theirs, base, region, group.filter(c => c.side === 'theirs'))
    const baseLines = base.slice(start, end)
    regions.push({ kind: 'changed', mine: mineLines, base: baseLines, theirs: theirLines })
    baseAt = end
  }
  if (baseAt < base.length) regions.push({ kind: 'stable', lines: base.slice(baseAt) })
  return regions
}

/** How a changed region resolves: both, mine, theirs or a conflict. */
export function resolve(region) {
  if (sameLines(region.mine, region.theirs)) return 'both'
  if (sameLines(region.mine, region.base)) return 'theirs'
  if (sameLines(region.theirs, region.base)) return 'mine'
  return 'conflict'
}

