export function mergeLines(regions, withBase) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'stable') {
      out.push(...region.lines)
      continue
    }
    const how = resolve(region)
    if (how === 'both' || how === 'mine') out.push(...region.mine)
    else if (how === 'theirs') out.push(...region.theirs)
    else {
