    if (region.kind === 'stable') {
      out.push(...region.lines)
      continue
    }
    const how = resolve(region)
    if (how === 'both' || how === 'mine') out.push(...region.mine)
    else if (how === 'theirs') out.push(...region.theirs)
    else {
      conflicted = true
      out.push('<<<<<<< mine')
      out.push(...region.mine)
      if (withBase) {
        out.push('||||||| base')
        out.push(...region.base)
      }
      out.push('=======')
      out.push(...region.theirs)
      out.push('>>>>>>> theirs')
    }
  }
  return { lines: out, conflicted }
}

/** The one-line report of each region. */
export function regionLines(regions) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'stable') {
      out.push(`stable ${region.lines.length}`)
      continue
    }
    const how = resolve(region)
    if (how === 'conflict') {
      conflicted = true
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else if (how === 'theirs') out.push(`theirs ${region.theirs.length}`)
    else out.push(`${how} ${region.mine.length}`)
  }
  return { lines: out, conflicted }
}
